def solve(inputs: dict) -> float:
    a = inputs['TERMS']
    p_prev1, p_prev2 = 0, 1

    for term in reversed(a):
        p_new = term * p_prev1 + p_prev2
        p_prev2, p_prev1 = p_prev1, p_new

    return (p_prev2)

